        ('fetch 1, fetch 2, found o-130 - finally only runs when the generator finishes on its own, and break just abandons it.', false),
        ('fetch 1, fetch 2, fetch 3, found o-130, cleanup - the generator prefetches the next page while the loop body runs.', false),
        ('fetch 1, fetch 2, found o-130, then the generator keeps fetching in the background until fetchOrders returns an empty page, then cleanup.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_411'), 'const it = orders(); (the same generator as above). Which statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'Calling an async generator function only creates the generator object; the body starts on the first next(). for await...of closes the iterator with return() on every abrupt exit of the loop - break, return, or an exception thrown by the loop body. A rejection inside the generator (fetchOrders failing) is not swallowed: next() rejects and the for await loop throws it at the loop. A generator object is a single-use iterator, not a re-iterable collection: two loops over the same object share one cursor position, and once one of them closes it, the other gets nothing more.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_411') AND order_index = 2)
    RETURNING id
)
