WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_421'), '"Café au lait" is sent as UTF-8. The "é" is two bytes (0xC3 0xA9), and the network delivers chunk 1 = "Caf" + 0xC3 and chunk 2 = 0xA9 + " au lait". The client runs:

const decoder = new TextDecoder();
let text = '''';
for (const chunk of [chunk1, chunk2]) text += decoder.decode(chunk);

What is text?', 'single_choice'::question_type, 'Without { stream: true }, every decode() call treats its input as a complete document. The lone 0xC3 at the end of chunk 1 is an incomplete sequence and becomes U+FFFD; the lone 0xA9 at the start of chunk 2 is an invalid continuation byte and becomes a second U+FFFD. decode(chunk, { stream: true }) instead keeps the incomplete bytes inside the decoder and joins them with the next chunk, and a final decode() flushes what is left. The default decoder is not fatal, so it never throws - it replaces silently, which is why this bug reaches production.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_421') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('"Café au lait" - the decoder remembers the 0xC3 byte and joins it with the next call.', false),
        ('"Caf�� au lait" - each call decodes its chunk as a complete text, so both halves of the é become replacement characters.', true),
        ('decode() throws a TypeError on the first chunk because it ends with an incomplete character.', false),
        ('"Caf au lait" - incomplete bytes are dropped silently and the é disappears.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_421'), 'The export endpoint streams one JSON row per line. Which statements about const reader = response.body.getReader() and reader.read() are true? (Select all that apply.)', 'multiple_choice'::question_type, 'A chunk is whatever the network stack and the buffers in between happen to deliver: it can contain many rows, part of a row, or end inside a multi-byte character - one server write() does not map to one read(). getReader() locks the stream: while the lock is held, nobody else can read it, pipe it or get another reader, until releaseLock() (or the stream is cancelled through the reader). When the stream ends, read() resolves to { done: true, value: undefined }: the last data chunk was already delivered by the previous read().', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_421') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Chunk boundaries come from the network and buffering, not from the data: a chunk can end in the middle of a row or inside a multi-byte character.', true),
        ('While the reader holds the lock, the stream cannot be read, piped or given another reader until releaseLock() is called.', true),
        ('If the server calls write() once per row, each reader.read() resolves with exactly one row.', false),
        ('The final read() resolves to { done: true, value: lastChunk }, so the last chunk must be handled after the loop.', false)
    ) AS o(option_text, is_correct);

