-- challenge chal_quiz_js_511 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_js_511', (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901') AND order_index = 5 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-js-5-1' AND is_deleted = false LIMIT 1), 'debounce-or-throttle-quiz', 'Debounce, throttle or neither?', 'Three handlers on the same product page fire far too often. Pick the right rate-shaping tool for each one.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_511'), 'The product editor autosaves the description while the merchant types. Saving on every keystroke sends 300 PUT requests per paragraph. Product wants: save once the merchant pauses, and never lose more than 5 seconds of typing if they type non-stop for minutes. Which setup fits?', 'single_choice'::question_type, 'A trailing debounce waits for the pause and then saves the latest text, which is exactly what an autosave needs. On its own it would never fire for a user who never pauses, so maxWait bounds how long unsaved text can pile up. A throttle would save mid-word on a fixed rhythm and could miss the final keystrokes unless it has a trailing call; a leading debounce saves the first keystroke of a burst, which is the least useful version of the text.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_511') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Trailing debounce (e.g. 1000 ms) with maxWait 5000 ms, saving the latest value.', true),
        ('Leading debounce: save on the first keystroke, ignore the rest of the burst.', false),
        ('Throttle at 5000 ms without a trailing call, so at most one save per 5 seconds.', false),
        ('No rate shaping: just cancel the previous PUT with AbortController on each keystroke.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_511'), 'Two more handlers on the page: (1) a sticky header that shrinks according to the current scroll position, (2) the "Place order" button, which customers sometimes double-click and create two orders. Which pairing is right?', 'single_choice'::question_type, 'Scroll-driven UI must keep updating while the user scrolls, so it needs a regular cadence: throttle it (ideally aligned to animation frames) - a debounce would freeze the header until scrolling stops. A double-click guard must act on the FIRST click immediately and swallow the clicks that follow within a short window: that is a leading-edge debounce with no trailing call. The server should still be idempotent, but the UI guard removes most duplicates.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_511') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('(1) trailing debounce 200 ms, (2) trailing debounce 500 ms.', false),
        ('(1) throttle to about one update per frame, (2) leading debounce with trailing disabled.', true),
        ('(1) leading debounce, (2) throttle at 1000 ms with a trailing call.', false),
