-- challenge chal_quiz_js_611 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_js_611', (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901') AND order_index = 6 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-js-6-1' AND is_deleted = false LIMIT 1), 'fake-timers-test-hangs-quiz', 'Why does the fake-timer test still time out?', 'The retry test was switched to fake timers to make it fast. Now it never finishes. Find the reason before you read on.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_611'), 'fetchWithRetry(api, { delayMs: 1000 }) calls api(); on failure it waits with setTimeout(delayMs) and calls api() again. This Vitest test times out after 5 seconds:

test(''retries once after 1s'', async () => {
  vi.useFakeTimers();
  const api = vi.fn()
    .mockRejectedValueOnce(new Error(''503''))
    .mockResolvedValueOnce(''ok'');

  const result = await fetchWithRetry(api, { delayMs: 1000 });
  vi.advanceTimersByTime(1000);

  expect(result).toBe(''ok'');
});

What is the cause?', 'single_choice'::question_type, 'With fake timers, the 1000 ms setTimeout only fires when the test advances the clock. But the test awaits fetchWithRetry first, and fetchWithRetry cannot resolve until that timer fires. The line that would advance time is never reached: a deadlock, not a slow test. Start the operation without awaiting it, advance time with the async variant (await vi.advanceTimersByTimeAsync(1000)) so promise callbacks get to run between timers, and only then await the stored promise. Fake timers do work with promises, a rejected mock is handled by the retry code, and 1000 ms is enough because a timer due at exactly now + 1000 fires when the clock reaches it.', 1, 10
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_611') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Fake timers do not support promises, so code that awaits inside a timer callback can only be tested with real timers.', false),
        ('The test awaits fetchWithRetry before advancing the clock, but the promise can only settle after the fake 1000 ms timer fires - the advance is never reached.', true),
        ('mockRejectedValueOnce produces an unhandled rejection, which stops the test runner from processing timers.', false),
        ('advanceTimersByTime(1000) is one millisecond short: a timer created with 1000 ms only fires after 1001 ms have passed.', false)
    ) AS o(option_text, is_correct);

