-- challenge chal_quiz_js_613 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_js_613', (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901') AND order_index = 6 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-js-6-1' AND is_deleted = false LIMIT 1), 'advance-sync-vs-async-quiz', 'Three seconds passed, but only one poll ran', 'The fake clock moved forward, yet the code under test barely moved. Explain the gap between timers and promise callbacks.', 'open', 'hard'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_613'), 'pollJob(getStatus) calls the async function getStatus(); when it resolves with ''pending'', it schedules the next poll with setTimeout(poll, 1000). The test:

vi.useFakeTimers();
const getStatus = vi.fn().mockResolvedValue(''pending'');
pollJob(getStatus);            // first call happens immediately
vi.advanceTimersByTime(3000);
expect(getStatus).toHaveBeenCalledTimes(4);

The assertion fails: getStatus was called once. Why?', 'single_choice'::question_type, 'The next setTimeout is created inside a .then/await continuation - a microtask that only runs when the current synchronous code finishes. vi.advanceTimersByTime(3000) is fully synchronous: when it starts, no poll timer exists yet, because the first getStatus() promise has not delivered its result. It moves the clock 3 seconds with nothing to fire. await vi.advanceTimersByTimeAsync(3000) awaits between timers, giving promise continuations a turn, so each poll can schedule the next one. vi.runAllTimers() is just as synchronous as advanceTimersByTime and has the same problem; real timers would work but make the test slow and flaky.', 1, 10
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_613') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('advanceTimersByTime is synchronous: the timer for the next poll is only created in a promise continuation, which cannot run until the test yields, so there was no timer to fire.', true),
        ('Fake timers only advance setTimeout created before vi.useFakeTimers(), and pollJob created its timers afterwards.', false),
        ('mockResolvedValue resolves only once; later calls return undefined, so polling stops after the first call.', false),
        ('Replacing the advance with vi.runAllTimers() fixes it, because runAllTimers keeps going until the timer queue is empty.', false)
    ) AS o(option_text, is_correct);

