-- challenge chal_quiz_js_621 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_js_621', (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'javascript-async-architecture_2026100901') AND order_index = 6 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-js-6-2' AND is_deleted = false LIMIT 1), 'boolean-soup-impossible-state-quiz', 'What does the screen show after a failed search?', 'Three independent variables describe one request. Follow them through a failure and a successful retry.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_621'), 'A job-search panel keeps its request state in three variables and renders with:

if (error) return <ErrorBanner />;
if (isLoading) return <Spinner />;
return <Results items={data} />;

The loader is:

async function load(query) {
  isLoading = true;
  try {
    data = await api.search(query);
  } catch (e) {
    error = e;
  } finally {
    isLoading = false;
  }
}

The user searches ''plumber'' and the request fails. They search ''electrician'' and that request succeeds. What does the panel show?', 'single_choice'::question_type, 'Nothing ever resets error, so after the second request error and data are both set at the same time - a combination that should be impossible. The render checks error first, so the user sees the error banner over perfectly good results. Three independent variables allow 2 x 2 x 2 combinations (more with data), and the code has to remember to keep them consistent in every branch. With a single status field (idle | loading | success | error), entering loading replaces the whole state and the stale error disappears by construction.', 1, 10
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_js_621') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('The results for ''electrician'', because the second request succeeded and set data.', false),
        ('The error banner, even though fresh results arrived: error is never cleared, so error and data are both set.', true),
        ('A spinner that never goes away, because isLoading is still true from the failed request.', false),
        ('An empty results list, because the failed request set data to undefined.', false)
    ) AS o(option_text, is_correct);

